import clsx from 'clsx';
import { isString } from 'lodash-es';
import React, { type HTMLAttributes } from 'react';

import { tooltipItem } from './EventItem.sty.js';
import { Flex } from '../../../../../../../layouts-core/flex/Flex.js';
import { PrimaryAtom } from '../../../../tooltip-atoms/components/PrimaryAtom.js';
import { SecondaryAtom } from '../../../../tooltip-atoms/components/SecondaryAtom.js';
import { EmojiShape } from '../../../../tooltip-atoms/shapes/EmojiShape.js';
import { IconShape } from '../../../../tooltip-atoms/shapes/IconShape.js';
import { TooltipItem } from '../../../section-components/TooltipItem.js';
import { TooltipSymbolContent } from '../../../section-components/TooltipSymbolContent.js';
import type { TooltipItemProps } from '../../../types/ChartTooltip.config.js';

export interface EvenItemProps
  extends HTMLAttributes<HTMLDivElement>,
    Pick<TooltipItemProps, 'showDivider'> {
  title: string;
  description: string;
  icon?: React.ReactNode | string;
  actions?: () => React.ReactElement;
}

export const EventItem = ({
  description,
  icon,
  title,
  actions,
  className,
  showDivider,
  ...rest
}: EvenItemProps) => {
  return (
    <TooltipItem
      actions={actions}
      className={clsx(tooltipItem({ hasIcon: !!icon }), className)}
      showDivider={showDivider}
      {...rest}
    >
      <Flex alignItems="center">
        {icon && (
          <TooltipSymbolContent>
            {isString(icon) ? (
              <EmojiShape>{icon}</EmojiShape>
            ) : (
              <IconShape>{icon}</IconShape>
            )}
          </TooltipSymbolContent>
        )}
        <Flex flexDirection="column" gap={0}>
          <PrimaryAtom style={{ textAlign: 'left' }}>{title}</PrimaryAtom>
          <SecondaryAtom style={{ textAlign: 'left' }}>
            {description}
          </SecondaryAtom>
        </Flex>
      </Flex>
    </TooltipItem>
  );
};

EventItem['displayName'] = 'ChartTooltip.EventItem';
